import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p97_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor sdpa_forward_cuda(torch::Tensor q, torch::Tensor k, torch::Tensor v);

torch::Tensor sdpa_forward(torch::Tensor q, torch::Tensor k, torch::Tensor v) {
    TORCH_CHECK(q.is_cuda() && k.is_cuda() && v.is_cuda(), "All tensors must be CUDA");
    TORCH_CHECK(q.scalar_type() == torch::kFloat32, "Only float32 supported");
    TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && v.dim() == 4, "Expected 4D tensors");
    TORCH_CHECK(q.sizes() == k.sizes() && q.sizes() == v.sizes(), "Q, K, V must have same shape");
    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous(), "Tensors must be contiguous");
    return sdpa_forward_cuda(q, k, v);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("sdpa_forward", &sdpa_forward, "Fused Scaled Dot-Product Attention");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused scaled softmax kernel: operates on scores [BH, L, L]
// Each block handles one row of the attention matrix
// scale is applied before softmax
__global__ void scaled_softmax_kernel(
    float* __restrict__ scores,  // [BH, L, L]
    int L,
    float scale
) {
    // blockIdx.x = row index in [BH * L]
    int row = blockIdx.x;
    int bh = row / L;
    int qi = row % L;

    float* row_ptr = scores + (long)bh * L * L + (long)qi * L;

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // Step 1: find max with scale applied
    float local_max = -1e38f;
    for (int j = tid; j < L; j += block_size) {
        float val = row_ptr[j] * scale;
        if (val > local_max) local_max = val;
    }

    // Warp reduce max
    __shared__ float smem[32];
    int lane = tid & 31;
    int warp = tid >> 5;

    // Warp-level reduce
    for (int offset = 16; offset > 0; offset >>= 1)
        local_max = fmaxf(local_max, __shfl_down_sync(0xffffffff, local_max, offset));

    if (lane == 0) smem[warp] = local_max;
    __syncthreads();

    int num_warps = (block_size + 31) / 32;
    if (warp == 0) {
        float val = (lane < num_warps) ? smem[lane] : -1e38f;
        for (int offset = 16; offset > 0; offset >>= 1)
            val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
        if (lane == 0) smem[0] = val;
    }
    __syncthreads();
    float row_max = smem[0];

    // Step 2: compute exp(x - max) and sum
    float local_sum = 0.0f;
    for (int j = tid; j < L; j += block_size) {
        float val = __expf(row_ptr[j] * scale - row_max);
        row_ptr[j] = val;
        local_sum += val;
    }

    // Warp reduce sum
    for (int offset = 16; offset > 0; offset >>= 1)
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);

    if (lane == 0) smem[warp] = local_sum;
    __syncthreads();

    if (warp == 0) {
        float val = (lane < num_warps) ? smem[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1)
            val += __shfl_down_sync(0xffffffff, val, offset);
        if (lane == 0) smem[0] = val;
    }
    __syncthreads();
    float row_sum = smem[0];

    // Step 3: normalize
    float inv_sum = 1.0f / row_sum;
    for (int j = tid; j < L; j += block_size) {
        row_ptr[j] *= inv_sum;
    }
}

torch::Tensor sdpa_forward_cuda(torch::Tensor q, torch::Tensor k, torch::Tensor v) {
    int B = q.size(0);
    int H = q.size(1);
    int L = q.size(2);
    int D = q.size(3);
    int BH = B * H;

    float scale = 1.0f / sqrtf((float)D);

    // Reshape to [BH, L, D] for batched matmul
    auto q3 = q.view({BH, L, D});
    auto k3 = k.view({BH, L, D});
    auto v3 = v.view({BH, L, D});

    // scores = Q @ K^T: [BH, L, L]
    auto scores = torch::bmm(q3, k3.transpose(1, 2));

    // Fused scale + softmax
    int threads = 256;
    int blocks = BH * L;
    scaled_softmax_kernel<<<blocks, threads>>>(
        scores.data_ptr<float>(),
        L,
        scale
    );

    // out = scores @ V: [BH, L, D]
    auto out3 = torch::bmm(scores, v3);

    return out3.view({B, H, L, D});
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if (Q.is_cuda && Q.scalar_type() == torch::kFloat32 &&
            Q.dim() == 4 && K.dim() == 4 && V.dim() == 4 &&
            Q.sizes() == K.sizes() && Q.sizes() == V.sizes() &&
            Q.is_contiguous() && K.is_contiguous() && V.is_contiguous()):
            out = _stark_get_extension().sdpa_forward(Q, K, V)
        else:
            out = torch.nn.functional.scaled_dot_product_attention(Q, K, V)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return out
        # <<<END_IMPROVE>>>

