#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Specialized kernel for L==512: one block per row, 512 threads
// Each thread owns exactly one score element
__global__ void scaled_softmax_512_kernel(
    float* __restrict__ scores,  // [BH, L, L]
    int L,
    float scale
) {
    int row = blockIdx.x;  // row in [BH * L]
    int bh = row / L;
    int qi = row % L;
    float* row_ptr = scores + (long)bh * L * L + (long)qi * L;

    int tid = threadIdx.x;  // tid in [0, 512)

    // Load and scale
    float val = row_ptr[tid] * scale;

    // Warp-level max reduction
    float warp_max = val;
    for (int offset = 16; offset > 0; offset >>= 1)
        warp_max = fmaxf(warp_max, __shfl_down_sync(0xffffffff, warp_max, offset));

    // 512 threads = 16 warps
    __shared__ float smem_max[16];
    int lane = tid & 31;
    int warp = tid >> 5;
    if (lane == 0) smem_max[warp] = warp_max;
    __syncthreads();

    float row_max;
    if (warp == 0) {
        float v = (lane < 16) ? smem_max[lane] : -1e38f;
        for (int offset = 8; offset > 0; offset >>= 1)
            v = fmaxf(v, __shfl_down_sync(0xffffffff, v, offset));
        if (lane == 0) smem_max[0] = v;
    }
    __syncthreads();
    row_max = smem_max[0];

    // Compute exp
    float e = __expf(val - row_max);

    // Warp-level sum reduction
    float warp_sum = e;
    for (int offset = 16; offset > 0; offset >>= 1)
        warp_sum += __shfl_down_sync(0xffffffff, warp_sum, offset);

    __shared__ float smem_sum[16];
    if (lane == 0) smem_sum[warp] = warp_sum;
    __syncthreads();

    float row_sum;
    if (warp == 0) {
        float v = (lane < 16) ? smem_sum[lane] : 0.0f;
        for (int offset = 8; offset > 0; offset >>= 1)
            v += __shfl_down_sync(0xffffffff, v, offset);
        if (lane == 0) smem_sum[0] = v;
    }
    __syncthreads();
    row_sum = smem_sum[0];

    row_ptr[tid] = e / row_sum;
}

// Generic kernel: one block per row, variable threads
__global__ void scaled_softmax_generic_kernel(
    float* __restrict__ scores,
    int L,
    float scale
) {
    int row = blockIdx.x;
    int bh = row / L;
    int qi = row % L;
    float* row_ptr = scores + (long)bh * L * L + (long)qi * L;

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    float local_max = -1e38f;
    for (int j = tid; j < L; j += block_size) {
        float v = row_ptr[j] * scale;
        if (v > local_max) local_max = v;
    }

    __shared__ float smem[32];
    int lane = tid & 31;
    int warp = tid >> 5;
    int num_warps = (block_size + 31) / 32;

    for (int offset = 16; offset > 0; offset >>= 1)
        local_max = fmaxf(local_max, __shfl_down_sync(0xffffffff, local_max, offset));
    if (lane == 0) smem[warp] = local_max;
    __syncthreads();
    if (warp == 0) {
        float v = (lane < num_warps) ? smem[lane] : -1e38f;
        for (int offset = 16; offset > 0; offset >>= 1)
            v = fmaxf(v, __shfl_down_sync(0xffffffff, v, offset));
        if (lane == 0) smem[0] = v;
    }
    __syncthreads();
    float row_max = smem[0];

    float local_sum = 0.0f;
    for (int j = tid; j < L; j += block_size) {
        float e = __expf(row_ptr[j] * scale - row_max);
        row_ptr[j] = e;
        local_sum += e;
    }

    for (int offset = 16; offset > 0; offset >>= 1)
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
    if (lane == 0) smem[warp] = local_sum;
    __syncthreads();
    if (warp == 0) {
        float v = (lane < num_warps) ? smem[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1)
            v += __shfl_down_sync(0xffffffff, v, offset);
        if (lane == 0) smem[0] = v;
    }
    __syncthreads();
    float row_sum = smem[0];

    float inv_sum = 1.0f / row_sum;
    for (int j = tid; j < L; j += block_size)
        row_ptr[j] *= inv_sum;
}

torch::Tensor sdpa_forward_cuda(torch::Tensor q, torch::Tensor k, torch::Tensor v) {
    int B = q.size(0);
    int H = q.size(1);
    int L = q.size(2);
    int D = q.size(3);
    int BH = B * H;

    float scale = 1.0f / sqrtf((float)D);

    auto q3 = q.view({BH, L, D});
    auto k3 = k.view({BH, L, D});
    auto v3 = v.view({BH, L, D});

    auto scores = torch::bmm(q3, k3.transpose(1, 2));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    int blocks = BH * L;

    if (L == 512) {
        scaled_softmax_512_kernel<<<blocks, 512, 0, stream>>>(
            scores.data_ptr<float>(), L, scale);
    } else {
        int threads = (L <= 256) ? 256 : 512;
        scaled_softmax_generic_kernel<<<blocks, threads, 0, stream>>>(
            scores.data_ptr<float>(), L, scale);
    }
    AT_CUDA_CHECK(cudaGetLastError());

    auto out3 = torch::bmm(scores, v3);
    return out3.view({B, H, L, D});
}
# <<<END_IMPROVE>>>
"""

