    float4 a1 = reinterpret_cast<float4*>(row_ptr + base)[1];
    float4 a2 = reinterpret_cast<float4*>(row_ptr + base)[2];
    float4 a3 = reinterpret_cast<float4*>(row_ptr + base)[3];

