    float v2  = a0.z * scale; float v3  = a0.w * scale;
    float v4  = a1.x * scale; float v5  = a1.y * scale;
    float v6  = a1.z * scale; float v7  = a1.w * scale;
    float v8  = a2.x * scale; float v9  = a2.y * scale;
    float v10 = a2.z * scale; float v11 = a2.w * scale;
