    float e0  = __expf(v0  - row_max); float e1  = __expf(v1  - row_max);
    float e2  = __expf(v2  - row_max); float e3  = __expf(v3  - row_max);
    float e4  = __expf(v4  - row_max); float e5  = __expf(v5  - row_max);
    float e6  = __expf(v6  - row_max); float e7  = __expf(v7  - row_max);
    float e8  = __expf(v8  - row_max); float e9  = __expf(v9  - row_max);
    float e10 = __expf(v10 - row_max); float e11 = __expf(v11 - row_max);
    float e12 = __expf(v12 - row_max); float e13 = __expf(v13 - row_max);
    float e14 = __expf(v14 - row_max); float e15 = __expf(v15 - row_max);

