    reinterpret_cast<float4*>(row_ptr + base)[0] = o0;
    reinterpret_cast<float4*>(row_ptr + base)[1] = o1;
    reinterpret_cast<float4*>(row_ptr + base)[2] = o2;
    reinterpret_cast<float4*>(row_ptr + base)[3] = o3;
