        __syncthreads();
        if (warp == 0) {
            v = (lane < num_warps) ? smem[lane] : -1e38f;
            v = warp_reduce_max(v);
            if (lane == 0) smem[0] = v;
        }
        __syncthreads();
        return smem[0];
