        int lane = tid & 31;
        int warp = tid >> 5;
        v = warp_reduce_sum(v);
        if (lane == 0) smem[warp] = v;
        __syncthreads();
        if (warp == 0) {
            v = (lane < num_warps) ? smem[lane] : 0.0f;
            v = warp_reduce_sum(v);
            if (lane == 0) smem[0] = v;
